from __future__ import annotations

import os
from typing import Any, Dict, List, Optional

import requests

OPENAI_API_KEY_ENV = "OPENAI_API_KEY"
OPENAI_BASE_URL = "https://api.openai.com/v1"
OPENAI_MODEL = "gpt-4.1-mini"


def _build_prompt(analysis: Dict[str, Any]) -> str:
    parts: List[str] = ["Summarize the visual analysis results concisely."]
    for key in ("labels", "objects", "text", "ocr_text", "description", "captions", "safety"):
        value = analysis.get(key)
        if value:
            parts.append(f"{key}: {value}")
    return "\n".join(parts)


def summarize_visual_analysis(
    analysis: Dict[str, Any],
    *,
    api_key: Optional[str] = None,
    model: str = OPENAI_MODEL,
    temperature: float = 0.2,
) -> str:
    key = api_key or os.environ.get(OPENAI_API_KEY_ENV)
    if not key:
        raise ValueError("OPENAI_API_KEY is required")

    payload = {
        "model": model,
        "input": _build_prompt(analysis),
        "temperature": temperature,
    }
    response = requests.post(
        f"{OPENAI_BASE_URL}/responses",
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    output = data.get("output", [])
    for item in output:
        content = item.get("content", [])
        for block in content:
            text = block.get("text")
            if text:
                return text.strip()

    raise RuntimeError("OpenAI response did not include summary text")

